  CONSTRAINT `lichhenkham_ibfk_3` FOREIGN KEY (`MaLich`) REFERENCES `lichlamviec` (`MaLich`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
